import {isContainer} from './catalog.js';
import {clamp} from './editor-core.js';
export function behavior(e){return {click:e.type==='clock'?'calendar':e.type==='volume'?'volume':e.type==='workspaces'?'activate':isContainer(e)||['text','shape','visualizer'].includes(e.type)?'none':e.type,scroll:e.type==='volume'?'volume':'none',workspaceCount:5,volumeStep:5,activeColor:'#b9f579',mutedColor:'#ddaaa3',...e.behavior};}
export function box(project,e){const parent=project.elements.find(p=>p.id===e.parentId);return {...e,x:e.x+(parent?.x||0),y:e.y+(parent?.y||0)};}
export function attach(project,e,parentId){const absolute=box(project,e),parent=project.elements.find(p=>p.id===parentId);if(parent&&(!isContainer(parent)||isContainer(e)))throw Error('Only widgets can be placed inside a Bar');e.parentId=parent?.id||null;e.x=clamp(absolute.x-(parent?.x||0),-10000,10000);e.y=clamp(absolute.y-(parent?.y||0),-10000,10000);}
export function family(project,id){return [...project.elements.filter(e=>e.id===id),...project.elements.filter(e=>e.parentId===id)];}
export function cloneFamily(elements){const ids=new Map(elements.map(e=>[e.id,crypto.randomUUID()]));return elements.map(e=>{const copy=structuredClone(e);copy.id=ids.get(e.id);copy.parentId=ids.get(e.parentId)||null;if(!copy.parentId){copy.x=clamp(copy.x+24,-10000,10000);copy.y=clamp(copy.y+24,-10000,10000);}return copy;});}
export function calendarCells(year,month){const date=new Date(year,month,1),offset=(date.getDay()+6)%7,count=new Date(year,month+1,0).getDate();return [...Array(offset).fill(null),...Array.from({length:count},(_,i)=>i+1)];}
export function simulation(){const values=new Map();return {get(e){if(!values.has(e.id))values.set(e.id,{volume:65,brightness:72,muted:false,active:1,connected:true,bluetooth:true,battery:78,charging:false,notifications:3,playing:false,track:0,cpu:24,memory:42,temperature:48,disk:37,gpu:31,uptime:'3h 24m'});const s=values.get(e.id);s.active=clamp(s.active,1,behavior(e).workspaceCount);return s;},reset(){values.clear();}};}
